class Solution { private lateinit var richerThan:Array<MutableList<Int>>;private lateinit var quiet:IntArray;private lateinit var answer:IntArray;fun loudAndRich(richer:Array<IntArray>,quiet:IntArray):IntArray{this.quiet=quiet;richerThan=Array(quiet.size){mutableListOf()};for(relation in richer)richerThan[relation[1]].add(relation[0]);answer=IntArray(quiet.size){-1};for(person in quiet.indices)dfs(person);return answer};private fun dfs(person:Int):Int{if(answer[person]>=0)return answer[person];var best=person;for(rich in richerThan[person]){val candidate=dfs(rich);if(quiet[candidate]<quiet[best])best=candidate};answer[person]=best;return best} }
